 });

+test("descuento global (propuesta 001): porcentaje sobre el total, IVA sobre el total descontado", () => {
+  const items = [{ cantidad: 2, precioUnitarioCentavos: 1000 }];
+  assert.deepEqual(calcularFactura(items, { descuentoGlobal: 10 }), {
+    totalCentavos: 1800, ivaCentavos: 234, netoCentavos: 1566, descuentoCentavos: 200,
+  });
+  // sin descuento (o 0) el resultado no cambia
+  assert.deepEqual(calcularFactura(items), calcularFactura(items, { descuentoGlobal: 0 }));
+  // redondeo al centavo
+  assert.equal(calcularFactura([{ cantidad: 1, precioUnitarioCentavos: 1001 }], { descuentoGlobal: 10 }).descuentoCentavos, 100);
+  // 100 % deja el total en cero
+  assert.equal(calcularFactura(items, { descuentoGlobal: 100 }).totalCentavos, 0);
+  // fuera de 0–100 o no numérico se rechaza
+  for (const d of [-1, 101, NaN, "10"]) assert.throws(() => calcularFactura(items, { descuentoGlobal: d }), RangeError);
+});
+
 test("RF-003: una factura emitida no se puede modificar", () => {
